      // Ensure that the map contains the required keys.
      // Note 1: the values aren't checked for validity beyond being non-null.
      // Note 2: this code is stripped in release mode!
      assert(() {
        requiredKeys.forEach((key) {
          assert(json.containsKey(key), 'Required key "IamProvider[$key]" is missing from JSON.');
          assert(json[key] != null, 'Required key "IamProvider[$key]" has a null value in JSON.');
        });
        return true;
      }());

      return IamProvider(
        appId: mapValueOfType<String>(json, r'appId'),
        bucket: mapValueOfType<String>(json, r'bucket'),
        category: mapValueOfType<String>(json, r'category'),
        cert: mapValueOfType<String>(json, r'cert'),
        clientId: mapValueOfType<String>(json, r'clientId'),
        clientId2: mapValueOfType<String>(json, r'clientId2'),
