  static List<IamProvider> listFromJson(dynamic json, {bool growable = false,}) {
    final result = <IamProvider>[];
    if (json is List && json.isNotEmpty) {
      for (final row in json) {
        final value = IamProvider.fromJson(row);
        if (value != null) {
          result.add(value);
        }
      }
    }
    return result.toList(growable: growable);
  }

  static Map<String, IamProvider> mapFromJson(dynamic json) {
    final map = <String, IamProvider>{};
    if (json is Map && json.isNotEmpty) {
      json = json.cast<String, dynamic>(); // ignore: parameter_assignments
      for (final entry in json.entries) {
        final value = IamProvider.fromJson(entry.value);
        if (value != null) {
          map[entry.key] = value;
        }
      }
    }
    return map;
  }

  // maps a json object with a list of IamProvider-objects as value to a dart map
  static Map<String, List<IamProvider>> mapListFromJson(dynamic json, {bool growable = false,}) {
    final map = <String, List<IamProvider>>{};
    if (json is Map && json.isNotEmpty) {
      // ignore: parameter_assignments
      json = json.cast<String, dynamic>();
      for (final entry in json.entries) {
        map[entry.key] = IamProvider.listFromJson(entry.value, growable: growable,);
      }
    }
    return map;
  }

